const papers = [];
const entries = document.querySelectorAll('dl > dt');
const descriptions = document.querySelectorAll('dl > dd');
for (let i = 0; i < entries.length; i++) {
  const dt = entries[i];
  const idMatch = dt.textContent.match(/arXiv:(\d+\.\d+)/);
  const dd = descriptions[i];
  if (idMatch && dd) {
    const titleEl = dd.querySelector('.list-title');
    const title = titleEl ? titleEl.textContent.replace(/\s+/g, ' ').trim().replace(/Title:/i, '').trim() : '';
    const authorsEl = dd.querySelector('.list-authors');
    const authors = authorsEl ? authorsEl.textContent.replace(/\s+/g, ' ').trim().replace(/Authors:/i, '').trim() : '';
    const subjectsEl = dd.querySelector('.list-subjects');
    const subjects = subjectsEl ? subjectsEl.textContent.replace(/\s+/g, ' ').trim().replace(/Subjects:/i, '').trim() : '';
    papers.push({
      id: idMatch[1],
      title: title,
      authors: authors,
      subjects: subjects
    });
  }
}
return { totalPapers: papers.length, firstFew: papers.slice(0, 3), lastFew: papers.slice(-3) };

const dateHeaders = document.querySelectorAll('h3, h2, h4');
const dayMarkers = [];
for (const h of dateHeaders) {
  const text = h.textContent.trim();
  if (text.match(/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun),/)) {
    dayMarkers.push({ date: text, position: h.getBoundingClientRect().top + window.scrollY });
  }
}

// Alternative: find by content
const allHeaders = document.querySelectorAll('div#content h3, div#content h2, .listings-date');
const headersByContent = [];
for (const h of allHeaders) {
  const text = h.textContent.trim();
  if (text.match(/Sep|Oct|Nov|Dec/)) {
    headersByContent.push({ date: text, parentId: h.parentElement?.id || h.id });
  }
}

return { dateHeaders: dayMarkers.slice(0, 10), headersByContent: headersByContent.slice(0, 10), totalHeaders: allHeaders.length };

